// A comparator returns:
//   negative -> a comes before b
//   zero     -> equal
//   positive -> a comes after b

// Contract: it must be consistent and transitive.
// If a < b and b < c, then a < c, otherwise sort may throw an exception.

fun largestNumber(nums: IntArray): String {
    val strs = nums.map { it.toString() }
    // a before b if a+b is bigger than b+a
    val sorted = strs.sortedWith { a, b -> (b + a).compareTo(a + b) }
    if (sorted[0] == "0") return "0"          // all zeros
    return sorted.joinToString("")
}
// Time: O(n log n * L)   Space: O(n * L), L = digits per number

fun frequencySort(s: String): String {
    val freq = s.groupingBy { it }.eachCount()
    return s.toList()
        .sortedWith(compareByDescending<Char> { freq[it] }.thenBy { it })
        .joinToString("")
}
// Time: O(n log n)   Space: O(n)

fun sortByBits(arr: IntArray): IntArray {
    return arr.sortedWith(
        compareBy({ Integer.bitCount(it) }, { it })      // bit count, then value
    ).toIntArray()
}
// Time: O(n log n)   Space: O(n)

fun canAttendMeetings(intervals: Array<IntArray>): Boolean {
    intervals.sortBy { it[0] }
    for (i in 1 until intervals.size) {
        if (intervals[i][0] < intervals[i - 1][1]) return false
    }
    return true
}
// Time: O(n log n)   Space: O(1) extra

fun merge(intervals: Array<IntArray>): Array<IntArray> {
    intervals.sortBy { it[0] }
    val result = mutableListOf<IntArray>()
    for (iv in intervals) {
        if (result.isEmpty() || result.last()[1] < iv[0]) result.add(iv)
        else result.last()[1] = maxOf(result.last()[1], iv[1])
    }
    return result.toTypedArray()
}
// Time: O(n log n)   Space: O(n)

fun hasPairWithSum(nums: IntArray, target: Int): Boolean {
    nums.sort()
    var l = 0
    var r = nums.size - 1
    while (l < r) {
        val sum = nums[l] + nums[r]
        when {
            sum == target -> return true
            sum < target -> l++
            else -> r--
        }
    }
    return false
}
// Time: O(n log n)   Space: O(1)

fun findContentChildren(greed: IntArray, cookies: IntArray): Int {
    greed.sort()
    cookies.sort()
    var child = 0
    for (cookie in cookies) {
        if (child < greed.size && cookie >= greed[child]) child++
    }
    return child
}
// Time: O(n log n + m log m)   Space: O(1)

fun sortColors(nums: IntArray) {
    val count = IntArray(3)
    for (x in nums) count[x]++
    var i = 0
    for (color in 0..2) {
        repeat(count[color]) { nums[i++] = color }
    }
}
// Time: O(n)   Space: O(1)
// Use counting sort when the value range is small

fun topKFrequent(nums: IntArray, k: Int): IntArray {
    val freq = HashMap<Int, Int>()
    for (x in nums) freq[x] = (freq[x] ?: 0) + 1

    // bucket[i] holds numbers that appear i times
    val buckets = Array(nums.size + 1) { mutableListOf<Int>() }
    for ((num, count) in freq) buckets[count].add(num)

    val result = mutableListOf<Int>()
    for (i in buckets.indices.reversed()) {
        for (num in buckets[i]) {
            result.add(num)
            if (result.size == k) return result.toIntArray()
        }
    }
    return result.toIntArray()
}
// Time: O(n)   Space: O(n)

fun relativeSortArray(arr1: IntArray, arr2: IntArray): IntArray {
    val rank = HashMap<Int, Int>()
    for ((i, v) in arr2.withIndex()) rank[v] = i
    return arr1.sortedWith(
        compareBy({ rank[it] ?: Int.MAX_VALUE }, { it })   // known order first, rest ascending
    ).toIntArray()
}
// Time: O(n log n)   Space: O(m)

fun kClosest(points: Array<IntArray>, k: Int): Array<IntArray> {
    return points
        .sortedBy { it[0] * it[0] + it[1] * it[1] }     // squared distance, no sqrt
        .take(k)
        .toTypedArray()
}
// Time: O(n log n)   Space: O(n)
// Faster: a max heap of size k gives O(n log k), see Top K Elements

data class Task(val name: String, val priority: Int, val duration: Int) : Comparable<Task> {
    override fun compareTo(other: Task): Int {
        // higher priority first, then shorter duration
        return when {
            priority != other.priority -> other.priority.compareTo(priority)
            else -> duration.compareTo(other.duration)
        }
    }
}

val tasks = listOf(Task("a", 1, 5), Task("b", 3, 2), Task("c", 3, 1))
tasks.sorted()                         // uses compareTo
tasks.sortedWith(compareBy { it.name })    // override with a comparator

fun findKthLargest(nums: IntArray, k: Int): Int {
    val target = nums.size - k                   // index in sorted order
    var left = 0
    var right = nums.size - 1
    while (true) {
        val pivot = nums[right]
        var store = left
        for (i in left until right) {
            if (nums[i] < pivot) {
                val t = nums[i]; nums[i] = nums[store]; nums[store] = t
                store++
            }
        }
        val t = nums[store]; nums[store] = nums[right]; nums[right] = t
        when {
            store == target -> return nums[store]
            store < target -> left = store + 1
            else -> right = store - 1
        }
    }
}
// Time: O(n) average, O(n²) worst   Space: O(1)
